        while True:
            if length % 2 == 0:
                length += 1
                continue

            half = (length + 1) // 2
            start = 10 ** (half - 1)
            end = 10 ** half
            for prefix in range(start, end):
                s = str(prefix)
                candidate = int(s + s[-2::-1])
                if candidate >= n and is_prime(candidate):
                    return candidate
            length += 1

