static bool is_prime(int x) {
    if (x < 2) return false;
    if (x % 2 == 0) return x == 2;
    for (int d = 3; d <= x / d; d += 2) {
        if (x % d == 0) return false;
    }
    return true;
}

static int make_palindrome(int prefix) {
    int x = prefix / 10;
    long long result = prefix;
    while (x > 0) {
        result = result * 10 + (x % 10);
        x /= 10;
    }
    return (int)result;
}

int primePalindrome(int n) {
    if (n >= 8 && n <= 11) return 11;

    int digits = 0;
    for (int x = n; x > 0; x /= 10) ++digits;
    if (digits == 2) digits = 3;

    while (1) {
        if (digits % 2 == 0) { ++digits; continue; }
        int half = (digits + 1) / 2;
        int start = 1;
        for (int i = 1; i < half; ++i) start *= 10;
        int end = start * 10;
        for (int prefix = start; prefix < end; ++prefix) {
            int candidate = make_palindrome(prefix);
            if (candidate >= n && is_prime(candidate)) return candidate;
        }
        ++digits;
    }
}

