import java.io.*;

class Solution {
    private boolean isPrime(int x) {
        if (x < 2) return false;
        if (x % 2 == 0) return x == 2;
        for (int d = 3; (long) d * d <= x; d += 2) {
            if (x % d == 0) return false;
        }
        return true;
    }

    private int makePalindrome(int prefix) {
        int x = prefix / 10;
        long result = prefix;
        while (x > 0) {
            result = result * 10 + x % 10;
            x /= 10;
        }
        return (int) result;
    }

    public int primePalindrome(int n) {
        if (n >= 8 && n <= 11) return 11;
        int digits = String.valueOf(n).length();
        if (digits == 2) digits = 3;

        while (true) {
            if (digits % 2 == 0) { digits++; continue; }
            int half = (digits + 1) / 2;
            int start = 1;
            for (int i = 1; i < half; i++) start *= 10;
            int end = start * 10;
            for (int prefix = start; prefix < end; prefix++) {
                int candidate = makePalindrome(prefix);
                if (candidate >= n && isPrime(candidate)) return candidate;
            }
            digits++;
        }
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        String digits = line.replaceAll("[^0-9]", "");
        int n = Integer.parseInt(digits);
        System.out.println(new Solution().primePalindrome(n));
    }
}

